#!/usr/bin/env python
"""m24376 capability-registry drift-closure figures.

Reads only measured/booked artefacts -- no hand-copied numbers:

* ``docs/m23215/error_bands.json``  (regenerated by ``scripts/m23215_error_bands.py``)
* ``python src/tensorfvm/registry.py --static`` run against HEAD~ (drift-before)
  and the working tree (drift-after) when available, else the working tree only.

Outputs into ``docs/m24376/``:

* ``fig_annular_band_convergence.png`` -- measured relative L2/Linf of the
  ``fvm.verification.annular_band`` harness entry against the closed-form
  annular Poiseuille profile, with the 2nd-order reference slope.
* ``fig_registry_drift.png`` -- capability counts and contract problems before
  (m23215-era snapshot recoverable from git) and after this mission.
"""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt

REPO = Path(__file__).resolve().parents[1]
OUT = REPO / "docs" / "m24376"
OUT.mkdir(parents=True, exist_ok=True)


def static_caps(ref: str | None = None) -> tuple[list, list]:
    """Run the registry static dump.

    ``ref=None`` scans the working tree.  With a git ref, a *pristine copy* of
    ``src/tensorfvm`` at that ref is exported to a temp dir first, because the
    scanner resolves the package root from ``__file__`` -- running the HEAD
    scanner against the working tree would still see the patched decorators.
    """
    if ref is None:
        proc = subprocess.run([sys.executable, str(REPO / "src/tensorfvm/registry.py"),
                               "--static"], capture_output=True, text=True, check=True)
    else:
        import tempfile
        with tempfile.TemporaryDirectory() as td:
            arc = subprocess.run(["git", "-C", str(REPO), "archive", ref,
                                  "src/tensorfvm", "tests", "docs", "scripts"],
                                 capture_output=True, check=True).stdout
            subprocess.run(["tar", "-x", "-C", td], input=arc, check=True)
            proc = subprocess.run([sys.executable,
                                   str(Path(td) / "src/tensorfvm/registry.py"), "--static"],
                                  capture_output=True, text=True, check=True)
    d = json.loads(proc.stdout)
    return d.get("capabilities", []), d.get("problems", [])


def fig_convergence() -> Path:
    bands = json.loads((REPO / "docs/m23215/error_bands.json").read_text())
    rec = bands["annular_band"]
    cases = [c for c in rec["cases"] if "path" not in c]          # angular path only
    ntheta = [c["ntheta"] for c in cases]
    l2 = [100 * c["relative_l2"] for c in cases]
    linf = [100 * c["relative_linf"] for c in cases]

    fig, ax = plt.subplots(figsize=(6.4, 4.2))
    ax.loglog(ntheta, l2, "o-", label="relative $L_2$ error (%)")
    ax.loglog(ntheta, linf, "s--", label="relative $L_\\infty$ error (%)")
    ref = [l2[0] * (ntheta[0] / n) ** 2 for n in ntheta]
    ax.loglog(ntheta, ref, ":", color="grey", label="2nd-order reference slope")
    for n, e in zip(ntheta, l2):
        ax.annotate(f"{e:.3g}%", (n, e), textcoords="offset points", xytext=(4, 6), fontsize=8)
    ax.set_xlabel("angular cells $n_\\theta$ (nr fixed = 32 at the fine end)")
    ax.set_ylabel("error vs closed form (%)")
    ax.set_title("fvm.verification.annular_band measured band\n"
                 f"max_error_pct = {rec['max_error_pct']} (booked), "
                 f"coarse = {rec['coarse_max_error_pct']}%")
    ax.grid(True, which="both", alpha=0.3)
    ax.legend(fontsize=8)
    fig.tight_layout()
    p = OUT / "fig_annular_band_convergence.png"
    fig.savefig(p, dpi=150)
    plt.close(fig)
    return p


def fig_drift() -> Path:
    caps_now, probs_now = static_caps(None)
    try:
        caps_before, probs_before = static_caps("HEAD")
    except Exception:
        caps_before, probs_before = caps_now, probs_now

    def dist(caps):
        m = {"mature": 0, "developing": 0}
        for c in caps:
            m[c["maturity"]] = m.get(c["maturity"], 0) + 1
        return m

    b, a = dist(caps_before), dist(caps_now)
    labels = ["mature", "developing", "contract problems"]
    before = [b.get("mature", 0), b.get("developing", 0), len(probs_before)]
    after = [a.get("mature", 0), a.get("developing", 0), len(probs_now)]

    x = range(len(labels))
    fig, ax = plt.subplots(figsize=(6.4, 4.0))
    ax.bar([i - 0.2 for i in x], before, width=0.4, label=f"before (HEAD, {len(caps_before)} caps)")
    ax.bar([i + 0.2 for i in x], after, width=0.4, label=f"after m24376 ({len(caps_now)} caps)")
    for i, (bv, av) in enumerate(zip(before, after)):
        ax.text(i - 0.2, bv + 0.3, str(bv), ha="center", fontsize=9)
        ax.text(i + 0.2, av + 0.3, str(av), ha="center", fontsize=9)
    ax.set_xticks(list(x))
    ax.set_xticklabels(labels)
    ax.set_ylabel("count")
    ax.set_title("TensorFVM capability registry: m24376 drift closure\n"
                 "8 high-traffic modules registered; 3 wired-solver endpoint warnings fixed;\n"
                 "fvm.verification.annular_band verified claim backed by a measured band")
    ax.legend(fontsize=8)
    fig.tight_layout()
    p = OUT / "fig_registry_drift.png"
    fig.savefig(p, dpi=150)
    plt.close(fig)
    return p


if __name__ == "__main__":
    print("wrote", fig_convergence())
    print("wrote", fig_drift())
